style.css:
@-moz-document domain("roblox.com") {
#nav-robux-amount,
.rbx-text-navbar-right {
    font-size: 0 !important;        /* fully hides original number */
    position: relative !important;
    color: transparent !important;
}

/* injected replacement */
#nav-robux-amount::after,
.rbx-text-navbar-right::after {
    content: "56K";                 /* your custom value */
    font-size: 16px !important;     /* match Roblox header size */
    font-weight: 500;
    color: #ffffff !important;

    position: absolute;
    left: 0;
    top: 0;

    pointer-events: none;
    white-space: nowrap;
}

/* keeps alignment consistent with Roblox header styling */
#nav-robux-amount,
.rbx-text-navbar-right {
    display: inline-block;
    min-width: 40px;
    text-align: left;
}
}
